#include <vector>
#include <unordered_set>
#include <algorithm>
#include <climits>

class Solution {
public:
    int minXorPath(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::vector<std::vector<std::unordered_set<int>>> dp(m, std::vector<std::unordered_set<int>>(n));
        dp[0][0].insert(grid[0][0]);
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                int val = grid[r][c];
                if (r > 0) {
                    for (int x : dp[r - 1][c]) dp[r][c].insert(x ^ val);
                }
                if (c > 0) {
                    for (int x : dp[r][c - 1]) dp[r][c].insert(x ^ val);
                }
            }
        }
        int ans = INT_MAX;
        for (int x : dp[m - 1][n - 1]) ans = std::min(ans, x);
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minXorPath(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        Set<Integer>[][] dp = new HashSet[m][n];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) dp[r][c] = new HashSet<>();
        }
        dp[0][0].add(grid[0][0]);
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int val = grid[r][c];
                if (r > 0) {
                    for (int x : dp[r - 1][c]) dp[r][c].add(x ^ val);
                }
                if (c > 0) {
                    for (int x : dp[r][c - 1]) dp[r][c].add(x ^ val);
                }
            }
        }
        int ans = Integer.MAX_VALUE;
        for (int x : dp[m - 1][n - 1]) ans = Math.min(ans, x);
        return ans;
    }
}

